changeSet.sql:
ALTER TABLE review DROP CONSTRAINT ck_review_origin;
ALTER TABLE review ADD CONSTRAINT ck_review_origin CHECK (origin IN ('EVENT','REQUEST','BACKFILL','SCHEDULE','TRIAL'));
ALTER TABLE review DROP CONSTRAINT ck_review_origin_links;
ALTER TABLE review ADD CONSTRAINT ck_review_origin_links CHECK ((event_id IS NULL OR origin='EVENT') AND (batch_id IS NULL OR origin IN ('BACKFILL','SCHEDULE')) AND (requested_by_id IS NULL OR origin IN ('REQUEST','TRIAL')));
ALTER TABLE review ADD CONSTRAINT ck_review_trial_kind CHECK (origin<>'TRIAL' OR kind='ITEM');
ALTER TABLE review DROP CONSTRAINT ck_review_report;
ALTER TABLE review ADD CONSTRAINT ck_review_report CHECK (report IS NULL OR ((kind='SCAN' OR origin='TRIAL') AND jsonb_typeof(report)='object'));
ALTER TABLE review_item DROP CONSTRAINT ck_review_item_state;
ALTER TABLE review_item ADD CONSTRAINT ck_review_item_state CHECK (state IN ('LISTED','STAGED','JUDGED','REUSED','WITHHELD','TRIED'));

rollback.sql:
DELETE FROM review WHERE origin='TRIAL';
